toolArgs.file_text:
@* Step indicator bar showing progress through the multi-step form *@

<nav aria-label="Application steps" class="step-indicator mb-4">
    <ol class="d-flex list-unstyled justify-content-between p-0 m-0">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var stepNumber = i + 1;
            var isCompleted = CompletedSteps.Contains(stepIndex);
            var isCurrent = stepIndex == CurrentStep;
            var isFuture = !isCompleted && !isCurrent;

            <li class="step-item flex-fill text-center @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")">
                @if (isCompleted)
                {
                    <button class="btn btn-link step-btn p-0 text-decoration-none w-100"
                            @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-circle bg-success text-white">✓</span>
                        <span class="step-label d-block mt-1 small text-success">@StepNames[stepIndex]</span>
                    </button>
                }
                else if (isCurrent)
                {
                    <div class="w-100">
                        <span class="step-circle bg-primary text-white">@stepNumber</span>
                        <span class="step-label d-block mt-1 small fw-bold text-primary">@StepNames[stepIndex]</span>
                    </div>
                }
                else
                {
                    <div class="w-100">
                        <span class="step-circle bg-secondary text-white opacity-50">@stepNumber</span>
                        <span class="step-label d-block mt-1 small text-muted">@StepNames[stepIndex]</span>
                    </div>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames =
    [
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    ];
}

