@page "/apply"
@rendermode InteractiveServer
@using sv_b84af04410484867a846b46ed8d8c181.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="personalInfo"
                              ApplicationService="ApplicationService"
                              OnNext="() => AdvanceFrom(0)" />
            break;

        case 1:
            <WorkHistoryStep Entries="workEntries"
                             OnNext="() => AdvanceFrom(1)"
                             OnBack="() => GoToStep(0)" />
            break;

        case 2:
            <ReferencesStep References="references"
                            OnNext="() => AdvanceFrom(2)"
                            OnBack="() => GoToStep(1)" />
            break;

        case 3:
            <CoverLetterStep @bind-CoverLetter="coverLetter"
                             OnNext="() => AdvanceFrom(3)"
                             OnBack="() => GoToStep(2)" />
            break;

        case 4:
            <ReviewStep Personal="personalInfo"
                        WorkEntries="workEntries"
                        References="references"
                        CoverLetter="coverLetter"
                        ApplicationService="ApplicationService"
                        OnBack="() => GoToStep(3)"
                        OnEditStep="GoToStep" />
            break;
    }
</div>

@code {
    private int currentStep;
    private readonly HashSet<int> completedSteps = new();

    private readonly PersonalInfoModel personalInfo = new();
    private readonly List<WorkEntryModel> workEntries = [new WorkEntryModel()];
    private readonly List<ReferenceModel> references = [new ReferenceModel(), new ReferenceModel()];
    private string coverLetter = "";

    private void AdvanceFrom(int step)
    {
        completedSteps.Add(step);
        currentStep = step + 1;
    }

    private void GoToStep(int step)
    {
        if (step == currentStep) return;
        if (step < currentStep || completedSteps.Contains(step))
        {
            currentStep = step;
        }
    }
}

